#include <print>

int main() {
    int minutes = 100;
    int hours = minutes / 60;
    int rest = minutes % 60;
    std::println("{} 分钟 = {} 小时 {} 分", minutes, hours, rest);

    int b = 3;
    // 10.0 改成 10 之后输出从 3.3333 变成 3
    std::println("{}", 10 / b);
    std::println("{:.4f}", 10.0 / b);
    return 0;
}

